// FX1 / FX2 (45.10b-5 red kit, testplan C.4): cr_scratch/step45_storyboard_v3/sim_export.json is regenerated by export_sim.py from the live sim and must not be stale.
//   values check (green when regenerated): START_MODE surface; l1 / pipe / main finish times equal goldens_v38 (S_GV1, S_GV2, S_P.GV4); RIG constants of v37.
//   stamp check (red until built): consts.sim_sha256 equals goldens_v38 _meta.sim_sha256; export_sim.py writes the stamp; ui/fixture.js refuses a mismatched stamp.
// Known-bad: a copy with one finish time +1e-3, a stale stamp, a v36 constant set. Adjacent: +1e-7 stays inside the 6e-4 export tolerance.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { ROOT, getGoldens } from '../lib/goldens.mjs';

const FX = path.join(ROOT, 'cr_scratch', 'step45_storyboard_v3', 'sim_export.json');
const EXPORTER = path.join(ROOT, 'cr_scratch', 'step45_storyboard_v3', 'export_sim.py');
const UI_FIXTURE = path.join(ROOT, 'game45', 'ui', 'fixture.js');
const TOL = 6e-4;

export function valueErrors(fx, G) {
  const e = [];
  const near = (label, a, b) => { if (!(Math.abs(a - b) <= TOL)) e.push(`${label}: ${a} != ${b}`); };
  if (fx.consts?.START_MODE !== 'surface') e.push(`consts.START_MODE ${fx.consts?.START_MODE} != surface`);
  near('l1.endL', fx.l1?.endL, G.S_GV1.left.end_s); near('l1.endR', fx.l1?.endR, G.S_GV1.right.end_s);
  near('pipe.goldens.endL', fx.pipe?.goldens?.endL, G.S_GV2.left.end_s); near('pipe.goldens.endR', fx.pipe?.goldens?.endR, G.S_GV2.right.end_s);
  near('main.goldens.base_endL', fx.main?.goldens?.base_endL, G.S_P.GV4.left.end_s); near('main.goldens.base_endR', fx.main?.goldens?.base_endR, G.S_P.GV4.right.end_s);
  if (fx.consts?.RIG_DRILL !== 1.7) e.push(`consts.RIG_DRILL ${fx.consts?.RIG_DRILL} != 1.7`);
  if (fx.consts?.RIG_TRAVEL !== 1800) e.push(`consts.RIG_TRAVEL ${fx.consts?.RIG_TRAVEL} != 1800`);
  return e;
}
export const stampErrors = (fx, G) => (fx.consts?.sim_sha256 === G._meta.sim_sha256 ? [] : [`consts.sim_sha256 ${String(fx.consts?.sim_sha256).slice(0, 12)} != _meta.sim_sha256 ${G._meta.sim_sha256.slice(0, 12)}`]);

const read = () => JSON.parse(fs.readFileSync(FX, 'utf8'));

test('FX1 values: sim_export.json carries surface mode, v37 rig constants and the v38 finish times', () => {
  assert.deepEqual(valueErrors(read(), getGoldens()), []);
});
test('FX1 values known-bad and adjacent: +1e-3 on l1.endR, a v36 constant set and START_MODE trunk are flagged; +1e-7 is inside the export tolerance', () => {
  const G = getGoldens();
  const a = read(); a.l1.endR += 1e-3; assert.ok(valueErrors(a, G).some((m) => /l1.endR/.test(m)));
  const b = read(); b.consts.RIG_DRILL = 5.0; b.consts.RIG_TRAVEL = 10; assert.equal(valueErrors(b, G).length, 2);
  const c = read(); c.consts.START_MODE = 'trunk'; assert.ok(valueErrors(c, G).some((m) => /START_MODE/.test(m)));
  const d = read(); d.l1.endR += 1e-7; assert.deepEqual(valueErrors(d, G), []);
});
test('FX1 stamp (red until export_sim.py writes it): consts.sim_sha256 equals goldens_v38 _meta.sim_sha256', () => {
  assert.deepEqual(stampErrors(read(), getGoldens()), []);
});
test('FX1 stamp detector: a stale stamp and a missing stamp are flagged; the matching stamp passes', () => {
  const G = getGoldens();
  const ok = read(); ok.consts.sim_sha256 = G._meta.sim_sha256; assert.deepEqual(stampErrors(ok, G), []);
  const stale = read(); stale.consts.sim_sha256 = '0'.repeat(64); assert.equal(stampErrors(stale, G).length, 1);
  const flipped = read(); flipped.consts.sim_sha256 = G._meta.sim_sha256.replace(/^./, (ch) => (ch === '0' ? '1' : '0')); assert.equal(stampErrors(flipped, G).length, 1);
  const none = read(); delete none.consts.sim_sha256; assert.equal(stampErrors(none, G).length, 1);
});
test('FX1 writers (red until built): export_sim.py writes consts.sim_sha256; ui/fixture.js compares it before building frames', () => {
  assert.match(fs.readFileSync(EXPORTER, 'utf8'), /sim_sha256/, 'export_sim.py does not write the sim stamp');
  assert.match(fs.readFileSync(UI_FIXTURE, 'utf8'), /sim_sha256/, 'ui/fixture.js has no staleness check');
});
